	const char* get_aiseq(AI_SEQUENCE sequence)
	{
		const char* str;

		switch (sequence)
		{
		case AIS_AWARE0:
			str = "on_aware0";
			break;
		case AIS_AWARE1:
			str = "on_aware0";
			break;
		case AIS_AWARE2:
			str = "on_aware0";
			break;
		case AIS_AWARE3:
			str = "on_aware0";
			break;
		default:
			str = "on_awarex";
		}

		return str;
	}

